sealed class ActiveStore {
    readonly Channel<Func<Task>> _q = Channel.CreateBounded<Func<Task>>(1024);
    public ActiveStore() => _ = Task.Run(async () => {
        await foreach (var work in _q.Reader.ReadAllAsync()) await work();  // scheduler
    });
    public Task PutAsync(Message m) {
        var tcs = new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);
        if (!_q.Writer.TryWrite(() => {
            try { servant.Put(m); tcs.SetResult(true); }
            catch (Exception ex) { tcs.SetException(ex); }
            return Task.CompletedTask;
        })) {
            tcs.SetException(new InvalidOperationException());
        }
        return tcs.Task;                                   // the future
    }
}

